contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public test function: attempts to call newEmergencyOracle and records whether it reverted,
    // then asserts that the call succeeds exactly when c.isAdmin(address(this)) is true.
    function run(string calldata description) public payable {
        // No precondition on description
        bool reverted;
        // Make the state-observing read before/after the call as allowed (public mapping getter)
        bool adminBefore = c.isAdmin(address(this)); if (__ESBMC_reverted()) return;

        // Attempt the potentially-reverting state-changing call as a top-level statement
        c.newEmergencyOracle(description); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // The general invariant: the call must succeed iff this contract is an admin in c
        assert(reverted == (!adminBefore));
    }

    // no-op receive so contract can accept Ether if needed in other tests
    receive() external payable {}
}

